class BscOperationError(Exception):
    """Raised if some operation on BSC cannot be performed"""


class TrxsLockFail(BscOperationError):
    """Raise if some TRX cannot be locked"""


class TrxsUnlockFail(BscOperationError):
    """Raise if some TRX cannot be unlocked"""


class SectorLockFail(BscOperationError):
    """Raise if some Sector cannot be locked"""


class SectorUnlockFail(BscOperationError):
    """Raise if some Sector cannot be unlocked"""


class SectorRemoveFail(BscOperationError):
    """Raise if some Sector cannot be deleted from bsc"""


class AuthorizationFailure(Exception):
    """Exception for invalid credentials"""


class BcfNotFound(Exception):
    """Raise if bcf has not been found"""

    def __init__(self, bcf_id):
        self.bcf_id = bcf_id

    def __str__(self):
        return "BCF-{} has not been found in BSC database".format(self.bcf_id)


class NoMatchError(Exception):
    """Exception for unexpected function output"""
